const perDay = 8 * 3;
function cost(days) {
  const drift = perDay * days;
  return Math.pow(drift, 1.5) / 50;
}
const c1 = cost(1), c3 = cost(3), c21 = cost(21);
console.log('day 1: drift=' + (perDay*1) + ' commits, merge cost=' + c1.toFixed(2) + ' min');
console.log('day 3: drift=' + (perDay*3) + ' commits, merge cost=' + c3.toFixed(2) + ' min');
console.log('day 21: drift=' + (perDay*21) + ' commits, merge cost=' + c21.toFixed(2) + ' min');
const ratio = (c21 / 1) / (c1 / 1);
console.log('cost ratio 21-day vs 1-day: ' + ratio.toFixed(1) + 'x');
console.log('21 daily merges would total: ' + (c1 * 21).toFixed(2) + ' min vs one big-bang: ' + c21.toFixed(2) + ' min');
